from .models import HuntStep,EmulationStep
from .store import uid
from .detection import atomic_candidates

def generate(extraction,source,context,coverage,candidates):
    env=context.environment_snapshot; hunts=[]; emulations=[]
    for b,row in zip(extraction.behaviors,coverage):
        if row.applicability!='applicable' or b.kind in ('unsupported','conflicting'): continue
        cs=[c for c in candidates if c.behavior_id==b.id]
        best=next((c for c in cs if c.query),None)
        query=('index=$INDEX$ earliest=$EARLIEST$ latest=$LATEST$ EventCode=1 '+best.query) if best and env.backend=='Splunk raw events' else None
        # These are analyst proposals, never assertions that source commands succeeded locally.
        steps=[{'order':1,'question':'Can this search answer the question for the selected time and host scope?','procedure':'Check source configuration and known benign events for each required field. Compare earliest retained event with the incident window. Record missing intervals and ingestion lag.','on_missing':'Stop automated interpretation; record telemetry gap and request source owner validation.'},
               {'order':2,'question':f'Is there evidence of {b.text}?','procedure':query or f'Review {", ".join(b.telemetry)} records for the source-described behavior on in-scope hosts. No tested backend query is available for this behavior. Preserve candidate records and exact procedure.','on_hit':'Preserve original events and query time bounds; pivot to process ancestry and user session.','on_no_hit':'If telemetry checks passed, record no matching evidence within the bounded search only; otherwise inconclusive.'},
               {'order':3,'question':'Is the observed action authorized and isolated, or part of a related sequence?','procedure':'Correlate host, user, process GUID/PID and event time with service installation, network connections and identity activity. Compare maintenance tickets and known tool owners. Do not infer unobserved stages.','on_suspicious':'Escalate with evidence, uncertainty and affected assets; request approved response containment.','on_benign':'Document authorization, matching control example and remaining visibility gaps.'}]
        if extraction.observables: steps.insert(2,{'order':3,'question':'Do source indicators corroborate the behavior?','procedure':'Search normalized malicious-role indicators in retained DNS/proxy/endpoint evidence. Never resolve or visit them. Treat historical values as leads, not automatic block recommendations.','parameters':[{'type':o.type,'value':o.value,'role':o.role} for o in extraction.observables if o.role=='malicious'],'on_no_hit':'No corroboration in retained data; continue behavior investigation.'}); steps[-1]['order']=4
        h=HuntStep(id=uid('hunt',context.customer_id,context.environment_id,b.id),behavior_id=b.id,evidence=b.evidence,assumptions=['Environment declaration is accurate','Analyst has approved access to retained logs','Source representation may be partial'],question='Was this reported behavior present in our environment?',hypothesis=f'An unauthorized operator may reproduce this observed behavior: {b.text}',priority='high' if b.key in ('lsass','rdp','activemq') else 'medium',rationale='Potential privileged access or business disruption; hypothesis is not a finding of compromise',scope=f'{context.customer_snapshot.name} / {env.name}; approved asset list only',prerequisites=b.telemetry+['Confirm event timestamps and retention boundaries'],required_fields=best.fields if best else env.telemetry.get(b.telemetry[0],[]) if b.telemetry else [],retention_days=env.retention_days,steps=steps,query=query,query_origin='pySigma conversion + explicit raw EventCode/index/time template' if query else 'hand-authored analyst procedure; no executable query available',backend=env.backend,field_mapping=env.field_map,parameters={'INDEX':'operator-selected actual raw-event index','EARLIEST':'operator-selected supported window','LATEST':'operator-selected window end'},expected='Behavior-consistent process/service/session evidence with host and user correlation',benign=['Authorized administration or software deployment','Security lab tests with documented scope'],negative_controls=['Known benign administrative action','Known event with required field deliberately omitted'],branches={'suspicious':'Preserve and escalate; correlate subsequent steps','no_hit_sufficient_telemetry':'Bounded no-evidence finding, never proof of no compromise','missing_telemetry':'Inconclusive; open improvement','benign':'Record authorization and residual gaps'},preserve=['Raw event export and hash','Query/procedure, UTC time bounds, timezone','Host/user/process identifiers','Analyst reasoning and ticket reference'],escalation='Unauthorized behavior with corroborating context or suspicious privileged activity merits IR review',closure='Close this hypothesis only with bounded findings, data sufficiency and unresolved gaps recorded')
        hunts.append(h);row.hunts.append(h.id)
        dangerous=b.key in ('activemq','lsass','rdp','remote_service')
        if b.key=='certutil':
            procedure=['In an isolated Windows lab, create a harmless text file on an analyst-controlled HTTP server with no Internet egress.','Confirm Sysmon process events arrive and Image/OriginalFileName/CommandLine fields survive ingestion.','After human approval, use certutil -urlcache -split -f http://<LAB_HOST>:<LAB_PORT>/harmless.txt <LAB_DIRECTORY>\\iti-harmless.txt. Substitute only the approved lab address.','Run the benign comparison certutil -store My. Preserve both process records, actual alert outcome and relevant control logs.']
        elif dangerous:
            procedure=['Do not execute the reported exploit, credential extraction, lateral payload or ransomware.','Replay a separately labeled synthetic event in the local matcher or approved isolated SIEM test index.','For actual control validation, have the control owner approve a benign vendor-supported simulation and document attempted action plus enforcement outcome.','Record this as a telemetry/control approximation; it does not reproduce compromise or ransomware prevention.']
        else:
            procedure=['Verify telemetry with an approved benign process event in an isolated Windows VM.','Have the analyst create a harmless command/process variant matching the relevant rule conditions, using only approved local tools and no persistence.','Run a known benign negative control.','Preserve raw records and separately record rule match, alert delivery, prevention and SOC handling if actually observed.']
        em=EmulationStep(id=uid('emulation',context.customer_id,context.environment_id,b.id),behavior_id=b.id,evidence=b.evidence,assumptions=['Human-led isolated lab only','Written lab scope approved outside this application'],objective=f'Can the declared control observe this variant of {b.text}?',applicability=row.reason,technique_id=b.technique_id,prerequisites=['Disposable Windows lab snapshot','Human test owner','No production credentials or attacker callbacks'],telemetry_checks=b.telemetry,lab_scope='Named disposable lab hosts and analyst-owned test data only',test_data='Harmless text file / synthetic events with example.invalid; never retrieve attacker infrastructure',steps=procedure,expected_observables=['Process/service/session event with UTC time and stable host identity','Required fields populated or explicit inconclusive result'],expected_detection='Evaluate named candidate rule independently from SIEM alert delivery',expected_prevention='Unknown until attempted benign control simulation and enforcing-control outcome are evidenced',benign_controls=['Authorized admin equivalent','Missing-field fixture to expose insufficient telemetry'],stop_conditions=['Any unexpected production connection','Unapproved privileged change','Unexpected file modification outside lab directory'],cleanup=['Remove only the named harmless test file','Stop analyst-owned lab HTTP server if used','Restore disposable snapshot for any approved configuration changes','Preserve evidence before cleanup'],atomic_candidates=atomic_candidates(b),limitations=['Synthetic replay is not adversary emulation','No full ATT&CK technique coverage claim','Missing Atomic match is an explicit catalog gap']+(['Dangerous stage not reproduced; use benign telemetry/control objective'] if dangerous else []),evidence_template={'environment_version':context.environment_version,'behavior_id':b.id,'control_id':'','control_version':'','procedure':'','expected':'','actual':'','executed_at':'UTC with offset','recorded_at':'assigned by application','method':'synthetic log match | lab emulation | observed SIEM alert | observed prevention | analyst attestation','evidence_reference':'','variant':'','exercise':'coordinated or blind'})
        from .php2shell_plans import tailor
        tailor(b,h,em)
        emulations.append(em);row.emulations.append(em.id);row.candidates=[c.id for c in cs];row.detection_readiness='candidate found; not deployed/verified' if cs else 'no relevant candidate in searched subset'
    return hunts,emulations

def render_markdown(title,package,key):
    import json
    lines=[f'# {title}',f'Customer: {package["context"]["customer_id"]} v{package["context"]["customer_version"]}; environment: {package["context"]["environment_id"]} v{package["context"]["environment_version"]}',f'Mode: {package["mode"]}; source completeness: {package["source"]["completeness"]}',f'Source: {package["source"]["origin"]}',f'Relevance: {package["relevance"]["rank"]} — {package["relevance"]["explanation"]}','\nThese are analyst proposals. Generated plans do not establish deployed or verified coverage.','\n## Extraction gaps']
    lines += ['- '+g for g in package['source']['gaps']] or ['None for supported content.']
    if not package[key]: lines.append('\nNo defensible applicable plan: insufficient supported evidence or selected environment mismatch. Inspect applicability reasons in manifest.')
    for i,item in enumerate(package[key],1):
        lines += [f'\n## {i}. '+item.get('hypothesis',item.get('objective','Step')),f'Behavior: {item["behavior_id"]}; supporting spans: '+', '.join(item['evidence'])]
        for k,v in item.items():
            if k in ('schema_version','id','behavior_id','evidence','hypothesis','objective'):continue
            if isinstance(v,list):
                lines += [f'\n### {k.replace("_"," ").title()}']+['- '+(x if isinstance(x,str) else json.dumps(x,ensure_ascii=False)) for x in v]
            elif isinstance(v,dict):lines += [f'\n**{k.replace("_"," ")}**', '```json',json.dumps(v,indent=2,ensure_ascii=False),'```']
            elif v is not None:lines += [f'\n**{k.replace("_"," ")}**: {v}']
    lines+=['\n## Rule attribution', 'Queries derived from Sigma rules retain their original authors and licenses. Preserve this attribution when sharing queries or messages based on rule matches.']
    for candidate in package.get('candidates',[]):
        if any(item['behavior_id']==candidate['behavior_id'] for item in package[key]):
            lines += [json.dumps({k:candidate.get(k) for k in ('id','title','author','license','source')},ensure_ascii=False)]
    lines += ['Detection Rule License 1.1: https://github.com/SigmaHQ/Detection-Rule-License']
    lines+=['\n## Evidence excerpts']
    refs={e for item in package[key] for e in item['evidence']}
    for span in package['source']['spans']:
        if span['id'] in refs: lines+=[f'\n{span["id"]} · {" / ".join(span["heading_path"])} · normalized {span["start"]}:{span["end"]}',span['text']]
    return '\n'.join(lines)+'\n'
